exercises.solution:
export function allFastPpm(fastPermille, fanout) {
  let ppm = 1_000_000;
  for (let i = 0; i < fanout; i += 1) {
    ppm = (ppm * fastPermille) / 1000;
  }
  return ppm;
}

export function anySlowPpm(fastPermille, fanout) {
  return 1_000_000 - allFastPpm(fastPermille, fanout);
}

