exercises.solution:
export function triesWithinDeadline(deadlineMs, tryTimeoutMs, backoffMs) {
  return Math.floor((deadlineMs + backoffMs) / (tryTimeoutMs + backoffMs));
}

export function timeUsedMs(tryTimeoutMs, backoffMs, tries) {
  return tries * tryTimeoutMs + (tries - 1) * backoffMs;
}

