  return edgeTimeoutMs - depth * perHopOverheadMs;
}

export function maxDepth(edgeTimeoutMs, perHopOverheadMs, minUsefulMs) {
  return Math.floor((edgeTimeoutMs - minUsefulMs) / perHopOverheadMs);
}

